    bg = max({v for row in grid for v in row},
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    def fill_diagonal(a, b, color):
        r1, c1 = a
        r2, c2 = b
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        for k in range(abs(r2 - r1) + 1):
            r, c = r1 + k * dr, c1 + k * dc
            if out[r][c] == bg:
                out[r][c] = color

    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    for i, p in enumerate(ones):
        for q in ones[i + 1:]:
            if p[0] != q[0] and abs(q[0] - p[0]) == abs(q[1] - p[1]):
                fill_diagonal(p, q, 1)

    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    used = set()
    for i, p in enumerate(sixes):
        for j in range(i + 1, len(sixes)):
